import concurrent.futures,datetime,json,math,pathlib,sys,time
ROOT=pathlib.Path('/mnt/selection')
OUT=pathlib.Path('/mnt/work/security.json')
ATTACKS=('primal_usvp','primal_bdd','dual','dual_hybrid')
MODELS=('BDGL16','MATZOV')
def integer_rms(sigma):
    return math.sqrt(math.fsum(2*k*k*.5*(math.erfc(k/(sigma*math.sqrt(2)))-math.erfc((k+1)/(sigma*math.sqrt(2)))) for k in range(1,math.ceil(12*sigma)+1)))
CASES={str(s):dict(n=1024,log_q=32,continuous_sigma=s,integer_rms=integer_rms(s)) for s in (3.2,128,256,512)}
def estimate(task):
    case,model,attack=task
    sys.path.insert(0,str(ROOT/'python/lattice-estimator'))
    sys.path.insert(0,str(ROOT/'python/estimates'))
    from estimator import LWE,ND,RC
    from sage.all import log
    from narrow_ckks_security import configure_max_beta
    configure_max_beta(4096)
    p=CASES[case]
    params=LWE.Parameters(n=p['n'],q=2**p['log_q'],Xs=ND.UniformMod(3),Xe=ND.DiscreteGaussian(p['integer_rms']),tag='small-ring-switch-'+case)
    t=time.monotonic()
    try:
        r=getattr(LWE,attack)(params,red_cost_model=getattr(RC,model))
        bits=float(log(r['rop'],2))
        if not math.isfinite(bits):raise ValueError('nonfinite optimizer result')
        return case,model,attack,dict(bits=bits,cost=str(r),seconds=time.monotonic()-t)
    except Exception as e:
        return case,model,attack,dict(error=type(e).__name__+': '+str(e),seconds=time.monotonic()-t)
def main():
    report=dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),parameter_selection_revision='036df9b06f2ab0954ce860351847b101621ea705',estimator_revision='3e48ef421ec256afddb3e7d2249a77eab6e9ba12',source='Parameter-Selection/python/lattice-estimator, using narrow_ckks_security.configure_max_beta',scope='Classical generic LWE proxy at effective small-ring dimension. Unbounded samples. Variance-matched discrete-Gaussian proxy for truncated continuous normal. Does not certify RLWE/ring-specific attacks, exact error PMF, cross-scheme circular/KDM security, or complete protocol security.',max_beta=4096,cases={k:dict(**v,models={m:{} for m in MODELS}) for k,v in CASES.items()})
    tasks=[(case,model,attack) for case in CASES for model in MODELS for attack in ATTACKS]
    with concurrent.futures.ProcessPoolExecutor(max_workers=4) as pool:
        futures=[pool.submit(estimate,t) for t in tasks]
        for f in concurrent.futures.as_completed(futures):
            case,model,attack,result=f.result();report['cases'][case]['models'][model][attack]=result
            OUT.write_text(json.dumps(report,indent=2)+'\n')
            print(case,model,attack,result.get('bits',result.get('error')),flush=True)
    for case,p in report['cases'].items():
        for model,results in p['models'].items():
            complete=all('bits' in results.get(a,{}) for a in ATTACKS)
            result=dict(complete=complete,weakest_bits=min((v['bits'] for v in results.values() if 'bits' in v),default=None))
            result['passes_128']=complete and result['weakest_bits']>=128
            p.setdefault('summary',{})[model]=result
            print('SUMMARY',case,model,result,flush=True)
    OUT.write_text(json.dumps(report,indent=2)+'\n')
if __name__=='__main__':main()
